# Terminator: proper search in downstream
down = seq[2854:]
def revcomp(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
print("\nTerminator search in downstream (2855-3000):")
best=[]
for i in range(len(down)-25):
    for L in range(8,16):
        stem = down[i:i+L]
        rc = revcomp(stem)
        for sp in range(3,10):
            j = i+L+sp
            if down[j:j+L] == rc:
                tail = down[j+L:j+L+15]
                tcount = tail.count('T')
                if tcount>=4:
                    best.append((2855+i, L, sp, stem, tail, tcount))
for b in sorted(best, key=lambda x:-x[6])[:5]:
    print("  stem at", b[0], "len", b[1], "spacer", b[2], "stem", b[3], "tail", b[4], "T-count", b[5])

